#!/bin/bash\n\n# اختبار سريع للتحقق من سلامة المشروع\necho \"🔍 بدء الاختبارات السريعة...\"\necho \"\"\n\n# 1. التحقق من وجود الملفات الأساسية\necho \"✓ التحقق من الملفات الأساسية\"\nfiles=(\n  \"package.json\"\n  \"tsconfig.json\"\n  \"vite.config.ts\"\n  \"README.md\"\n  \"all/src/router.tsx\"\n  \"all/src/start.ts\"\n)\n\nfor file in \"${files[@]}\"; do\n  if [ -f \"$file\" ]; then\n    echo \"  ✓ $file موجود\"\n  else\n    echo \"  ✗ $file غير موجود\"\n  fi\ndone\n\necho \"\"\n\n# 2. التحقق من الملفات المهمة\necho \"✓ التحقق من مكونات React\"\ncomponents=(\n  \"all/src/components/Dashboard.tsx\"\n  \"all/src/components/ClassPage.tsx\"\n  \"all/src/components/LoginPage.tsx\"\n  \"all/src/components/AdminPanel.tsx\"\n  \"all/src/hooks/useAuth.tsx\"\n  \"all/src/hooks/useIsAdmin.tsx\"\n)\n\nfor comp in \"${components[@]}\"; do\n  if [ -f \"$comp\" ]; then\n    echo \"  ✓ $comp موجود\"\n  else\n    echo \"  ✗ $comp غير موجود\"\n  fi\ndone\n\necho \"\"\necho \"✅ اكتمل الاختبار السريع!\"\necho \"\"\necho \"الخطوات التالية:\"\necho \"1. npm install          # تثبيت المكتبات\"\necho \"2. npm run dev          # تشغيل موقع التطوير\"\necho \"3. npm run lint         # فحص الأخطاء\"\n